import sys
print(sys.getrecursionlimit())  # 1000 by default in CPython

def count_reachable(graph, start):
    stack, seen = [start], {start}
    while stack:
        node = stack.pop()
        for nxt in graph.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return len(seen)

chain = {i: [i + 1] for i in range(10_000)}
print(count_reachable(chain, 0))  # 10001, no recursion

